export class Transmitter {
    /**
     * @param {Uint8Array} messageArray
     * @param {string} configSource
     * @returns {Uint8Array}
     */
    static sendCommand(messageArray: Uint8Array, configSource: string): Uint8Array;
    /**
     * @param {string} licenseKey
     * @returns {void}
     */
    static activate(licenseKey: string): void;
    /**
     * @param {string} configSource
     * @returns {void}
     */
    static setConfigSource(configSource: string): void;
    /**
     * @param {string} workingDirectory
     * @returns
     */
    static setWorkingDirectory(workingDirectory: string): void;
}
